; RAM
random          = $80    ; pseudo-random byte: shifted and XORed every frame ($F016)
thrustT         = $81    ; the T (thrust) arrow on the control panel; the button raises it. At MET 0 the launch needs it at $75 or more, else LAUNCH SCRUB
commandC0       = $82    ; the C (computer command) arrow, first of its two objects (moves with $83)
commandC1       = $83    ; the C arrow, second object
computerScreen  = $84    ; what the green computer screen shows: $D9A3 picks 1 (ground track) or 2 (docking radar); seen 0 ascent, 3 reentry, 4 landing, 5 before launch
statusPage      = $85    ; the status line page: odd values 1 SP, 3 ALT, 5 FUEL, 7 MET, 9 STAT, $0B FLT#, $0D X-AXIS, $0F Y-AXIS, $11 Z-AXIS, $13 PITCH, $15 YAW, $17 RNG, $19 NASA, $1B MISSION ABORT, $1D LAUNCH SCRUB, $1F RENDEZVOUS. A readout shows the three BCD bytes ending at $96 + page
cloud0X         = $86    ; x of the first cloud (pad and ascent window scene)
cloud1X         = $87    ; x of the second cloud
pitch           = $88    ; PITCH (status page $13 shows pitch*4-$1C: the ASLs leave carry clear, so SBC #$1B takes $1C; 0 = -28, 6 = -004, 13 = +24); docking needs 0
starRow         = $89    ; star field scroll position ($0E-$14) for the $8A-$95 table
starX           = $8A    ; x positions of 12 stars, $8A-$95 (rotated and shifted by the RCS motion flags $AB)
speedLo         = $96    ; SP readout, BCD, tenths of mach (low byte)
speedHi         = $97    ; SP readout, BCD (high byte): $97:$96 = 0231 is mach 23.1
altitudeLo      = $98    ; ALT readout, BCD, tenths of a nautical mile (low byte)
altitudeHi      = $99    ; ALT readout, BCD (high byte): $99:$98 = 2048 is 204.8 miles
fuelLo          = $9A    ; FUEL, BCD (low byte); burnt by BurnFuel ($FCAE), not in flights 1 and 2
fuelHi          = $9B    ; FUEL, BCD (high byte)
metLo           = $9C    ; MET (mission elapsed time), BCD seconds, low byte; holds at 15 during the countdown hold, counts down to 0, then up
metHi           = $9D    ; MET, high byte; $A0 while counting down
statLo          = $9E    ; STAT readout, low byte: before launch the switch check (4 primary, 20 backup, 40 doors: the manual's prelaunch messages), in flight the number of dockings (BCD)
statCode        = $9F    ; STAT readout, high byte: the abort message (hundreds), set by Abort ($FCC7): $10 runway, $15 early, $20 late, $30 nose gear, $35 banking turn, $40 gear, $50 doors at ascent/entry, $55/$60 pitch at entry, $65 yaw at entry, $70 too low, $75 too high, $80 too slow, $85 doors in orbit, $90 orbit angle at MECO, $95 too low/slow at MECO, $99 out of fuel
flight          = $A0    ; flight 1-3 (1 autosimulator, 2 simulator, 3 STS 101); Status steps it while the FLT# page shows
thrustOffCommand= $A1    ; $FF while the T arrow is off the C arrow (more fuel burns, the T arrow flashes)
axisLo          = $A2    ; signed readout for the axis pages, BCD (low byte)
axisHi          = $A3    ; signed readout, high byte ($A0 = minus)
altitudeTens    = $A4    ; altitude / 10, binary (follows $99)
altitude        = $A5    ; altitude in nautical miles, binary (follows $99:$98); the satellite is at 210 ($D2): docking needs it, Z-AXIS shows 210 - altitude
speed           = $A6    ; speed in tenths of mach, binary, up to 255 (follows $97:$96)
ram_AA          = $AA    ; ? the stick's up/down moves it between 0 and $21 during ascent; feeds $AD
motionFlags     = $AB    ; RCS motion of the view: bit 1 ?, 2 stars down, 4 stars right, 8 stars left (shift the star table)
preflightStep   = $AE    ; pre-launch check step, 1-9, one every 64 frames before the countdown starts
xAxis0          = $B0    ; X-AXIS readout = $B1 - $B0 (docking needs 0)
xAxis1          = $B1    ; see $B0
yAxis           = $B2    ; Y-AXIS (left/right offset from the satellite; docking needs 0)
yaw             = $B3    ; YAW (status page $15)
engineMode      = $B4    ; ? 0 engines off, 1 from lift-off, 5 from MET 3 (the launch events)
phase           = $B5    ; mission phase: 0 pad, 1 ascent, 2 orbit, 3 deorbit/entry, 4 landing
inFlight        = $B6    ; $FF from the countdown to the end of the flight
ticks           = $B9    ; +1 every frame ($D422); its wrap advances $BA
missionTicks    = $BA    ; +1 every 256 frames during a flight
launchEvent     = $BB    ; index into the launch event tables (MET of each event, what it does)
frameCount      = $C1    ; +1 every frame
metFrames       = $C5    ; frames until the next MET second (59-0)
switches        = $C6    ; SWCHB, read once a frame: bit 0 Activate Countdown (Reset), 1 Status (Select), 3 Primary Engines (Color = on), 6 Backup Engines (left A = on), 7 Cargo Doors/Landing Gear (right A = open/down)
statusHold      = $C7    ; Status switch hold timer: a new page every $30 frames held
soundStep       = $C9    ; step in the current sound effect ($FE: start)
sound           = $CA    ; the sound effect playing (0: none); PlaySound ($FCE6) starts one
soundTimer      = $CB    ; frames into the current step
digitPtr        = $CC    ; six 2-byte graphics pointers for the 48-pixel status line ($CC-$D7)
ram_DE          = $DE    ; ? positions an object at the end of the frame ($FCA2); docking needs it between $47 and $4F
entryGlow       = $E1    ; ? rises with speed between $78 and $A7 on the way down; the window flickers in the reentry color while random < it
dockHold        = $E2    ; frames held in the docking position; at $80 the docking counts
dockings        = $E3    ; successful dockings, up to 6
bayHeat         = $E6    ; cargo bay heat in orbit with the doors closed: alarm from $80, abort (85) at $FF; open doors reset it
touchdown       = $E8    ; $FF once the altitude reaches 0 on landing
range           = $E9    ; RNG readout during the landing (status page $17)
doorsOpen       = $F0    ; $FF while the cargo bay doors are open
fuelBurn        = $F5    ; fuel burnt each 16th frame by the main engines ($F054)
stickTouched    = $F7    ; $FF once the joystick moves: in flight 1 the pilot has taken over
simulator       = $F8    ; $FF in flights 1 and 2: no fuel used, most aborts overridden
autopilot       = $F9    ; $FF in flight 1 (the autosimulator) until the stick is touched
temp0           = $FA    ; scratch
temp1           = $FB    ; scratch
temp2           = $FC    ; scratch

