    bit $FFF8                 ; $F000
Reset:  ; power-on: clear the TIA and RAM, then InitRAM
    cld                       ; $F003
    ldx #$FF                  ; $F004
    txs                       ; $F006
    inx                       ; $F007
    txa                       ; $F008
LF009:
    sta VSYNC,x               ; $F009
    inx                       ; $F00B
    bne LF009                 ; $F00C
    jsr InitRAM               ; $F00E

; ---- The frame's game logic (during VBLANK)
FrameLogic:  ; top of every frame (after VSYNC): VBLANK timer, random number, frame counter, then the flight
    ldy #$29                  ; $F011
    sty TIM64T                ; $F013
    lda random                ; $F016  random: shift, XOR, rotate
    asl                       ; $F018
    asl                       ; $F019
    asl                       ; $F01A
    eor random                ; $F01B
    asl                       ; $F01D
    rol random                ; $F01E
    inc frameCount            ; $F020
    lda frameCount            ; $F022
    tay                       ; $F024
    and #$3F                  ; $F025
    bne FuelAndHeat           ; $F027
    lda phase                 ; $F029
    bne FuelAndHeat           ; $F02B
    lda preflightStep         ; $F02D
    beq FuelAndHeat           ; $F02F
    inc preflightStep         ; $F031
    cmp #$09                  ; $F033
    bne FuelAndHeat           ; $F035
    sta preflightStep         ; $F037
    lda inFlight              ; $F039
    bne FuelAndHeat           ; $F03B
    bit autopilot             ; $F03D
    bmi LF04A                 ; $F03F
    ldx #$09                  ; $F041
    lda switches              ; $F043  prelaunch switch check: (switches >> 1) & $64 = 4 primary, 20 backup, 40 doors (the manual's message numbers)
    lsr                       ; $F045
    and #$64                  ; $F046
    bne LF050                 ; $F048
LF04A:
    dec inFlight              ; $F04A
    sta computerScreen        ; $F04C
    ldx #$07                  ; $F04E
LF050:
    sta statLo                ; $F050
    stx statusPage            ; $F052
FuelAndHeat:  ; BurnFuel($F5); every 16th frame the bay heat +1 and, in flight, 1 fuel unit (+6 with engineMode set, +2 while T is off C)
    lda fuelBurn              ; $F054
    jsr BurnFuel              ; $F056
    tya                       ; $F059
    and #$0F                  ; $F05A
    bne LF076                 ; $F05C
    inc bayHeat               ; $F05E
    lda inFlight              ; $F060
    beq LF076                 ; $F062
    clc                       ; $F064
    lda #$01                  ; $F065
    ldx engineMode            ; $F067
    beq LF06D                 ; $F069
    adc #$06                  ; $F06B
LF06D:
    ldx thrustOffCommand      ; $F06D
    beq LF073                 ; $F06F
    adc #$02                  ; $F071
LF073:
    jsr BurnFuel              ; $F073
LF076:
    bit autopilot             ; $F076
    bpl LF084                 ; $F078
    lda altitude              ; $F07A
    cmp #$D2                  ; $F07C
    bne LF0DB                 ; $F07E
    lda #$00                  ; $F080
    beq LF08A                 ; $F082
LF084:
    lda switches              ; $F084
    and #$48                  ; $F086
    bne LF0DB                 ; $F088
LF08A:
    sta engineMode            ; $F08A
    ldx inFlight              ; $F08C
    beq LF0DB                 ; $F08E
    ldx phase                 ; $F090
    cpx #$01                  ; $F092
    bne LF0DB                 ; $F094
    stx motionFlags           ; $F096
    sta xAxis1                ; $F098
    inc phase                 ; $F09A
    sta sound                 ; $F09C
    sta bayHeat               ; $F09E
    ldx #$95                  ; $F0A0
    lda speed                 ; $F0A2
    cmp #$D2                  ; $F0A4
    bcc LF0B8                 ; $F0A6
    lda #$00                  ; $F0A8
    bit autopilot             ; $F0AA
    bmi LF0C3                 ; $F0AC
    ldx #$90                  ; $F0AE
    lda #$21                  ; $F0B0
    sbc ram_AA                ; $F0B2
    cmp #$08                  ; $F0B4
    bcc LF0BD                 ; $F0B6
LF0B8:
    jsr Abort                 ; $F0B8
    bcs LF0DB                 ; $F0BB
LF0BD:
    asl                       ; $F0BD
    asl                       ; $F0BE
    asl                       ; $F0BF
    asl                       ; $F0C0
    adc #$40                  ; $F0C1
LF0C3:
    sta xAxis0                ; $F0C3
    bit stickTouched          ; $F0C5
    bpl LF0CB                 ; $F0C7
    lda #$10                  ; $F0C9
LF0CB:
    bit autopilot             ; $F0CB
    bmi LF0D5                 ; $F0CD
    lda yAxis                 ; $F0CF
    asl                       ; $F0D1
    asl                       ; $F0D2
    asl                       ; $F0D3
    asl                       ; $F0D4
LF0D5:
    sta yAxis                 ; $F0D5
    inc $ED                   ; $F0D7
    inc computerScreen        ; $F0D9
LF0DB:
    lda engineMode            ; $F0DB
    beq LF0E8                 ; $F0DD
    tya                       ; $F0DF
    and #$02                  ; $F0E0
    bne LF150                 ; $F0E2
    lda $BC                   ; $F0E4
    beq LF0FD                 ; $F0E6
LF0E8:
    ldx commandC1             ; $F0E8
    lsr                       ; $F0EA
    bcs LF0F5                 ; $F0EB
LF0ED:
    dec commandC0             ; $F0ED
    dec commandC1             ; $F0EF
    cpx #$0D                  ; $F0F1
    bne LF0FD                 ; $F0F3
LF0F5:
    inc commandC0             ; $F0F5
    inc commandC1             ; $F0F7
    cpx #$81                  ; $F0F9
    beq LF0ED                 ; $F0FB
LF0FD:
    lda inFlight              ; $F0FD
    beq LF126                 ; $F0FF
    lda engineMode            ; $F101
    beq LF126                 ; $F103
    bit autopilot             ; $F105
    bpl LF10F                 ; $F107
    lda $BC                   ; $F109
    beq LF14C                 ; $F10B
    bpl LF123                 ; $F10D
LF10F:
    bit INPT4                 ; $F10F
    bmi LF14C                 ; $F111
    ldx $A9                   ; $F113
    bne LF121                 ; $F115
    inx                       ; $F117
    lda commandC0             ; $F118
    cmp thrustT               ; $F11A
    bcs LF11F                 ; $F11C
    inx                       ; $F11E
LF11F:
    stx $A9                   ; $F11F
LF121:
    lda $A9                   ; $F121
LF123:
    lsr                       ; $F123
    bcs LF129                 ; $F124
LF126:
    dec thrustT               ; $F126
    .byte $2C                 ; $F128 bit: skips the next instruction on this path
LF129:
    inc thrustT               ; $F129
    lda thrustT               ; $F12B
    cmp #$0F                  ; $F12D
    bcc LF129                 ; $F12F
    cmp #$8C                  ; $F131
    beq LF126                 ; $F133
    bit INPT4                 ; $F135
    bmi LF150                 ; $F137
    lda engineMode            ; $F139
    bne LF150                 ; $F13B
    lda inFlight              ; $F13D
    beq LF150                 ; $F13F
    lda phase                 ; $F141
    bne LF150                 ; $F143
    bit autopilot             ; $F145
    bmi LF150                 ; $F147
    jmp ScrubLaunch           ; $F149
LF14C:
    lda #$00                  ; $F14C
    sta $A9                   ; $F14E
LF150:
    tya                       ; $F150
    and #$1F                  ; $F151
    bne LF16F                 ; $F153
    ldx engineMode            ; $F155
    cpx #$05                  ; $F157
    beq LF16F                 ; $F159
    ldx #$9F                  ; $F15B
    dec cloud0X               ; $F15D
    lda cloud0X               ; $F15F
    bne LF165                 ; $F161
    stx cloud0X               ; $F163
LF165:
    and #$03                  ; $F165
    bne LF16F                 ; $F167
    dec cloud1X               ; $F169
    bne LF16F                 ; $F16B
    stx cloud1X               ; $F16D
LF16F:
    lda $ED                   ; $F16F
    beq ReadConsole           ; $F171
    inc $ED                   ; $F173
    bne ReadConsole           ; $F175
    ldx #$38                  ; $F177
    jsr PlaySound             ; $F179
    lda #$05                  ; $F17C
    sta $EC                   ; $F17E
ReadConsole:  ; the console switches: Activate Countdown (Reset) and Status (Select)
    lda SWCHB                 ; $F180
    sta switches              ; $F183
    lsr                       ; $F185
    bcs StatusSwitch          ; $F186
    lda statusHold            ; $F188
    ldx inFlight              ; $F18A
    beq LF196                 ; $F18C
    inc statusHold            ; $F18E
    cmp #$7F                  ; $F190
    bne MissionClock          ; $F192
    beq StartCountdown        ; $F194 (not executed in the coverage run)
LF196:
    cmp #$01                  ; $F196
    bne MissionClock          ; $F198
StartCountdown:  ; Activate Countdown: the flight's flags (autopilot, simulator), RAM cleared, pre-launch checks begin
    ldx #$FF                  ; $F19A
    ldy flight                ; $F19C
    cpy #$02                  ; $F19E
    bcs LF1A4                 ; $F1A0
    stx autopilot             ; $F1A2
LF1A4:
    cpy #$03                  ; $F1A4
    bcs LF1AA                 ; $F1A6
    stx simulator             ; $F1A8
LF1AA:
    jsr ClearFlightRAM        ; $F1AA
    sty flight                ; $F1AD
    ldy #$08                  ; $F1AF
    sty statusHold            ; $F1B1
    sty $B7                   ; $F1B3
    ldy #$00                  ; $F1B5
    sty missionTicks          ; $F1B7
    sty $B8                   ; $F1B9
    iny                       ; $F1BB
    sty preflightStep         ; $F1BC
LF1BE:
    jmp BuildStatusLine       ; $F1BE
StatusSwitch:  ; Status held: the next page every $30 frames; on the FLT# page before a flight it steps the flight number
    lsr                       ; $F1C1
    bcs LF208                 ; $F1C2
    dec statusHold            ; $F1C4
    bne MissionClock          ; $F1C6
    lda #$30                  ; $F1C8
    sta statusHold            ; $F1CA
    lda $F1                   ; $F1CC
    beq LF1D8                 ; $F1CE
    lda #$00                  ; $F1D0
    sta $F1                   ; $F1D2
    sta statCode              ; $F1D4
    beq LF1FE                 ; $F1D6
LF1D8:
    lda statusPage            ; $F1D8
    ldx $B7                   ; $F1DA
    bne LF1F3                 ; $F1DC
    cmp #$0B                  ; $F1DE
    beq LF1E6                 ; $F1E0
    ldx #$0B                  ; $F1E2
    bne LF1FC                 ; $F1E4
LF1E6:
    inc flight                ; $F1E6
    lda flight                ; $F1E8
    cmp #$04                  ; $F1EA
    bne LF1FE                 ; $F1EC
    inx                       ; $F1EE
    stx flight                ; $F1EF
    bne LF1FE                 ; $F1F1
LF1F3:
    adc #$02                  ; $F1F3
    tax                       ; $F1F5
    cmp #$0B                  ; $F1F6
    bcc LF1FC                 ; $F1F8
    ldx #$01                  ; $F1FA
LF1FC:
    stx statusPage            ; $F1FC
LF1FE:
    lda sound                 ; $F1FE
    bne MissionClock          ; $F200
    lda #$34                  ; $F202
    sta sound                 ; $F204
    bne MissionClock          ; $F206
LF208:
    lda #$01                  ; $F208
    sta statusHold            ; $F20A
MissionClock:  ; the MET clock, once a second while in flight
    lda inFlight              ; $F20C
    beq LF1BE                 ; $F20E
    dec metFrames             ; $F210
    bne LF286                 ; $F212
    sed                       ; $F214
    lda #$3B                  ; $F215
    sta metFrames             ; $F217
    lda metHi                 ; $F219
    cmp #$A0                  ; $F21B
    bne LF250                 ; $F21D
    ldx #$04                  ; $F21F
    jsr PlaySound             ; $F221
    ldx #$07                  ; $F224
    lda metLo                 ; $F226
    sbc #$01                  ; $F228
    sta metLo                 ; $F22A
    bne LF238                 ; $F22C
    ldx thrustT               ; $F22E  MET 0: enough thrust for lift-off?
    cpx #$75                  ; $F230
    bcc ScrubLaunch           ; $F232
    sta metHi                 ; $F234
    ldx #$03                  ; $F236
LF238:
    stx statusPage            ; $F238
    bne LaunchEvents          ; $F23A
ScrubLaunch:  ; MET reached 0 without enough thrust (T < $75): LAUNCH SCRUB, the clock back to 16
    sta launchEvent           ; $F23C
    sta engineMode            ; $F23E
    lda #$B8                  ; $F240
    sta metFrames             ; $F242
    ldx #$16                  ; $F244
    stx metLo                 ; $F246
    ldx #$41                  ; $F248
    stx sound                 ; $F24A
    ldx #$1D                  ; $F24C
    bne LF238                 ; $F24E
LF250:
    lda metLo                 ; $F250
    adc #$01                  ; $F252
    sta metLo                 ; $F254
    lda metHi                 ; $F256
    adc #$00                  ; $F258
    sta metHi                 ; $F25A
    bne LaunchEvents          ; $F25C
    ldx #$01                  ; $F25E
    lda metLo                 ; $F260
    cmp #$25                  ; $F262
    bne LF270                 ; $F264
    lda #$07                  ; $F266
    sta $EC                   ; $F268
    lda #$68                  ; $F26A
    sta sound                 ; $F26C
    bne LF276                 ; $F26E
LF270:
    cmp #$03                  ; $F270
    bne LaunchEvents          ; $F272
    ldx #$05                  ; $F274
LF276:
    stx engineMode            ; $F276
LaunchEvents:  ; the launch events at their MET (tables at $FEAB / $FE8D)
    cld                       ; $F278
    lda phase                 ; $F279
    cmp #$02                  ; $F27B
    bcs LF2A0                 ; $F27D
    ldx launchEvent           ; $F27F
    lda LaunchEventMet,x      ; $F281
    cmp metLo                 ; $F284
LF286:
    bne LF29A                 ; $F286
    inc launchEvent           ; $F288
    lda LaunchEventAction,x   ; $F28A
    and #$0F                  ; $F28D
    sta $BC                   ; $F28F
    cpx #$00                  ; $F291
    bne LF29A                 ; $F293
    inx                       ; $F295
    stx engineMode            ; $F296
    inc thrustT               ; $F298
LF29A:
    lda launchEvent           ; $F29A
    cmp #$03                  ; $F29C
    bcs LF2A3                 ; $F29E
LF2A0:
    jmp LF32C                 ; $F2A0
LF2A3:
    lda thrustT               ; $F2A3
    cmp #$10                  ; $F2A5
    bcs LF2AD                 ; $F2A7
    ldx engineMode            ; $F2A9
    beq LF2A0                 ; $F2AB
LF2AD:
    lsr                       ; $F2AD
    lsr                       ; $F2AE
    lsr                       ; $F2AF
    lsr                       ; $F2B0
    lsr                       ; $F2B1
    clc                       ; $F2B2
    adc #$0B                  ; $F2B3
    eor #$0F                  ; $F2B5
    adc #$14                  ; $F2B7
    dec $A8                   ; $F2B9
    bpl LF2C2                 ; $F2BB
    sta $A8                   ; $F2BD
    jsr SpeedUp               ; $F2BF
LF2C2:
    ldx speed                 ; $F2C2
    lda #$05                  ; $F2C4
    cpx #$20                  ; $F2C6
    bcc LF2CC                 ; $F2C8
    lda #$03                  ; $F2CA
LF2CC:
    cpx #$80                  ; $F2CC
    bcc LF2D2                 ; $F2CE
    lda #$01                  ; $F2D0
LF2D2:
    cpx #$D8                  ; $F2D2
    bcc LF2D8                 ; $F2D4
    lda #$00                  ; $F2D6
LF2D8:
    dec $A7                   ; $F2D8
    bpl AscentStick           ; $F2DA
    sta $A7                   ; $F2DC
    lda cloud0X               ; $F2DE
    sbc #$04                  ; $F2E0
    bcc LF2E6                 ; $F2E2
    sta cloud0X               ; $F2E4
LF2E6:
    lda cloud1X               ; $F2E6
    adc #$03                  ; $F2E8
    cmp #$A0                  ; $F2EA
    bcs LF2F0                 ; $F2EC
    sta cloud1X               ; $F2EE
LF2F0:
    jsr AltitudeUp            ; $F2F0
AscentStick:  ; ascent and entry: every 32 frames a random drift of Y-AXIS; the stick's left/right moves Y, up/down moves $AA
    lda frameCount            ; $F2F3
    and #$1F                  ; $F2F5
    bne LF328                 ; $F2F7
    lda random                ; $F2F9
    cmp #$B0                  ; $F2FB
    bcc LF307                 ; $F2FD
    lsr                       ; $F2FF
    bcs LF305                 ; $F300
    inc yAxis                 ; $F302
    .byte $2C                 ; $F304 bit: skips the next instruction on this path
LF305:
    dec yAxis                 ; $F305
LF307:
    lda SWCHA                 ; $F307
    asl                       ; $F30A
    bcs LF30F                 ; $F30B
    inc yAxis                 ; $F30D
LF30F:
    asl                       ; $F30F
    bcs LF314                 ; $F310
    dec yAxis                 ; $F312
LF314:
    ldy ram_AA                ; $F314
    asl                       ; $F316
    bcs LF31F                 ; $F317
    cpy #$21                  ; $F319
    beq LF31F                 ; $F31B
    inc ram_AA                ; $F31D
LF31F:
    asl                       ; $F31F
    bcs LF328                 ; $F320
    cpy #$00                  ; $F322
    beq LF328                 ; $F324
    dec ram_AA                ; $F326
LF328:
    cld                       ; $F328
    jmp DockingCheck          ; $F329
LF32C:
    lda phase                 ; $F32C
    cmp #$03                  ; $F32E
    beq AscentStick           ; $F330
    cmp #$04                  ; $F332
    bne LF34D                 ; $F334
    ldx #$17                  ; $F336
    bit INPT4                 ; $F338
    bmi LF33E                 ; $F33A
    ldx #$03                  ; $F33C
LF33E:
    stx statusPage            ; $F33E
    ldy #$01                  ; $F340
    lda SWCHA                 ; $F342
    and #$F0                  ; $F345
    cmp #$F0                  ; $F347
    beq LF3A5                 ; $F349
    dec $C0                   ; $F34B
LF34D:
    bne DockingCheck          ; $F34D
    ldx #$04                  ; $F34F
    stx $C0                   ; $F351
    tax                       ; $F353
    txa                       ; $F354
    asl                       ; $F355
    tax                       ; $F356
    bcs LF36B                 ; $F357
    dec yAxis                 ; $F359
    lda yAxis                 ; $F35B
    cmp #$FF                  ; $F35D
    bne LF365                 ; $F35F
    lda #$9F                  ; $F361
    sta yAxis                 ; $F363
LF365:
    cmp #$4F                  ; $F365
    bne LF36B                 ; $F367
    inc yAxis                 ; $F369
LF36B:
    txa                       ; $F36B
    asl                       ; $F36C
    tax                       ; $F36D
    bcs LF382                 ; $F36E
    inc yAxis                 ; $F370
    lda yAxis                 ; $F372
    cmp #$A0                  ; $F374
    bne LF37C                 ; $F376
    lda #$00                  ; $F378
    sta yAxis                 ; $F37A
LF37C:
    cmp #$50                  ; $F37C
    bne LF382                 ; $F37E
    dec yAxis                 ; $F380
LF382:
    lda $F3                   ; $F382
    bne DockingCheck          ; $F384
    lda sound                 ; $F386
    cmp #$98                  ; $F388
    beq DockingCheck          ; $F38A
    txa                       ; $F38C
    asl                       ; $F38D
    tax                       ; $F38E
    bcs LF399                 ; $F38F
    lda pitch                 ; $F391
    cmp #$10                  ; $F393
    beq DockingCheck          ; $F395
    inc pitch                 ; $F397
LF399:
    txa                       ; $F399
    asl                       ; $F39A
    bcs DockingCheck          ; $F39B
    lda pitch                 ; $F39D
    beq DockingCheck          ; $F39F
    dec pitch                 ; $F3A1
    bpl DockingCheck          ; $F3A3
LF3A5:
    sty $C0                   ; $F3A5
DockingCheck:  ; Y 0, pitch 0, $DE in $47-$4F, X 0 and altitude 210: count frames to a docking
    lda yAxis                 ; $F3A7
    bne LF407                 ; $F3A9
    lda pitch                 ; $F3AB
    bne LF407                 ; $F3AD
    lda ram_DE                ; $F3AF
    cmp #$50                  ; $F3B1
    bcs LF407                 ; $F3B3
    cmp #$47                  ; $F3B5
    bcc LF407                 ; $F3B7
    lda xAxis1                ; $F3B9
    sbc xAxis0                ; $F3BB
    bne LF407                 ; $F3BD
    lda altitude              ; $F3BF
    cmp #$D2                  ; $F3C1
    bne LF407                 ; $F3C3
LF3C5:
    inc dockHold              ; $F3C5  every axis lined up: count frames toward a docking
    bne LF3CB                 ; $F3C7
    dec dockHold              ; $F3C9 (not executed in the coverage run)
LF3CB:
    lda dockHold              ; $F3CB
    cmp #$80                  ; $F3CD
    bne LF3F5                 ; $F3CF
    ldx #$24                  ; $F3D1  docked: sound, the satellite sails off, another docking counted, fuel bonus
    stx sound                 ; $F3D3
    dec xAxis0                ; $F3D5
    ldx dockings              ; $F3D7
    cpx #$06                  ; $F3D9
    beq LF3DF                 ; $F3DB
    inc dockings              ; $F3DD
LF3DF:
    sed                       ; $F3DF
    clc                       ; $F3E0
    lda statLo                ; $F3E1
    adc #$01                  ; $F3E3
    sta statLo                ; $F3E5
    lda fuelHi                ; $F3E7
    adc DockingFuelBonus,x    ; $F3E9
    sta fuelHi                ; $F3EC
    bcc LF3F4                 ; $F3EE
    lda #$99                  ; $F3F0
    sta fuelHi                ; $F3F2
LF3F4:
    cld                       ; $F3F4
LF3F5:
    bcc LF416                 ; $F3F5
    ldx #$05                  ; $F3F7
    cmp #$FE                  ; $F3F9
    beq LF403                 ; $F3FB
    cmp #$FF                  ; $F3FD
    beq LF416                 ; $F3FF
    ldx #$1F                  ; $F401
LF403:
    stx statusPage            ; $F403
    bne LF45C                 ; $F405
LF407:
    lda dockHold              ; $F407
    cmp #$80                  ; $F409
    bcc LF412                 ; $F40B
    cmp #$FF                  ; $F40D
    bne LF3C5                 ; $F40F
    .byte $2C                 ; $F411 bit: skips the next instruction on this path
LF412:
    lda #$00                  ; $F412
    sta dockHold              ; $F414
LF416:
    lda phase                 ; $F416
    cmp #$04                  ; $F418
    bne OrbitLimits           ; $F41A
    lda altitude              ; $F41C
    cmp #$0B                  ; $F41E
    bcc OrbitLimits           ; $F420
    ldx autopilot             ; $F422
    bmi OrbitLimits           ; $F424
    lda SWCHA                 ; $F426 (not executed in the coverage run)
    cmp #$CF                  ; $F429 (not executed in the coverage run)
